    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Let's see what parts are different
    min_len = min(len(inp), len(outp))
    diff_start = -1
    diff_end = -1

    for j in range(min_len):
        if inp[j] != outp[j]:
            if diff_start == -1:
                diff_start = j
            diff_end = j

    if diff_start != -1:
        print(f"  Difference starts at index {diff_start}, ends at {diff_end}")
        print(f"  Input substring: '{inp[diff_start:diff_end+1]}'")
        print(f"  Output substring: '{outp[diff_start:diff_end+1]}'")
    else:
        if len(inp) != len(outp):
            print(f"  Length changed from {len(inp)} to {len(outp)}")
    print()

